<?php require __DIR__.'/_layout.php';$u=require_admin();$pdo=db();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{$act=$_POST['action']??'upload';if($act==='delete'){$id=(int)$_POST['id'];$st=$pdo->prepare("SELECT file_path FROM media WHERE id=?");$st->execute([$id]);$old=(string)$st->fetchColumn();$pdo->prepare("DELETE FROM media WHERE id=?")->execute([$id]);delete_local_media($old);go('galeria.php','Mídia removida.');}$type=$_POST['media_type']??'IMAGE';if(!in_array($type,['IMAGE','VIDEO'],true))$type='IMAGE';$files=$_FILES['files']??null;if(!$files || !is_array($files['name'])) throw new RuntimeException('Selecione um ou mais arquivos.');$count=0;for($i=0;$i<count($files['name']);$i++){if($files['error'][$i]===UPLOAD_ERR_NO_FILE)continue;$one=['name'=>$files['name'][$i],'type'=>$files['type'][$i],'tmp_name'=>$files['tmp_name'][$i],'error'=>$files['error'][$i],'size'=>$files['size'][$i]];$path=upload_file($one,$type==='IMAGE'?'image':'video');$pdo->prepare("INSERT INTO media(title,caption,media_type,file_path,event_date,featured,sort_order,published,created_at) VALUES(?,?,?,?,?,?,?,?,?)")->execute([trim($_POST['title']??''),trim($_POST['caption']??''),$type,$path,trim($_POST['event_date']??''),isset($_POST['featured'])?1:0,(int)($_POST['sort_order']??100),1,now_iso()]);$count++;}go('galeria.php',$count.' arquivo(s) adicionado(s).');}catch(Throwable $e){$err=$e->getMessage();}}$rows=$pdo->query("SELECT * FROM media WHERE media_type IN('IMAGE','VIDEO') ORDER BY id DESC")->fetchAll();admin_header('Galeria — Fotos e Vídeos');$msg=flash();?>
<?php if($msg):?><div class="alert ok"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?>
<form class="panel form-stack" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><h2>Upload múltiplo</h2><div class="grid2"><label>Tipo<select name="media_type"><option value="IMAGE">Fotos</option><option value="VIDEO">Vídeos</option></select></label><label>Arquivos<input type="file" name="files[]" multiple required accept="image/*,video/mp4,video/webm,video/quicktime"></label><label>Título geral<input name="title" placeholder="Ex.: Campeonato 2026"></label><label>Data<input type="date" name="event_date"></label></div><label>Legenda<textarea name="caption"></textarea></label><div class="grid2"><label>Ordem<input type="number" name="sort_order" value="100"></label><label class="check"><input type="checkbox" name="featured"> Destacar na página inicial</label></div><button class="primary">ENVIAR PARA GALERIA</button></form>
<div class="media-admin-grid"><?php foreach($rows as $r):?><article><?php if($r['media_type']==='IMAGE'):?><img src="../<?=e($r['file_path'])?>" alt=""><?php else:?><video controls preload="metadata"><source src="../<?=e($r['file_path'])?>"></video><?php endif;?><div><h3><?=e($r['title'])?></h3><p><?=e($r['caption'])?></p></div><form method="post" onsubmit="return confirm('Excluir esta mídia?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger">Excluir</button></form></article><?php endforeach;?></div>
<?php admin_footer();?>
